#include <stdio.h>
#include "jpleph.h"
int main(int argc,char **argv) {
    double a[6],b[6];
    void *e=jpl_init_ephemeris(argv[1],NULL,NULL);
    if(!e) return 2;
    double end=jpl_get_double(e,JPL_EPHEM_END_JD);
    int good=jpl_pleph(e,2450000.5,3,12,a,1);
    int failed=jpl_pleph(e,end-8,3,12,b,1);
    int repeated=jpl_pleph(e,end-8,3,12,b,1);
    int recovered=jpl_pleph(e,2450000.5,3,12,b,1);
    printf("%d %d %d %d %.17g\n",good,failed,repeated,recovered,b[0]-a[0]);
    jpl_close_ephemeris(e);return 0;
}
